graphql.query:
mutation CreateWallet($input: CreateWalletInput!) {
  createWallet(input: $input) { id label address network type balanceCache metadata ownerUserId status createdAt updatedAt }
}

mutation CreateRegtestWallet {
  createWallet(input: { label: "Postman GQL Regtest", network: REGTEST, type: NON_CUSTODIAL }) { id network type address metadata }
}

mutation CreateMainnetWallet {
  createWallet(input: { label: "Postman GQL Cold", network: MAINNET, type: COLD }) { id network type address status }
}

mutation BadEnum {
  createWallet(input: { label: "x", network: SIGNET, type: HOT }) { id }
}

mutation EmptyLabel {
  createWallet(input: { label: "", network: TESTNET, type: HOT }) { id }
}

mutation Anon {
  createWallet(input: { label: "anon", network: TESTNET, type: HOT }) { id }
}

query Wallet($id: ID!) {
  wallet(id: $id) { id label address network type balanceCache metadata ownerUserId status createdAt updatedAt }
}

query OtherWallet($id: ID!) {
  wallet(id: $id) { id }
}

query BadId {
  wallet(id: "not-an-id") { id }
}

query Forged($id: ID!) {
  wallet(id: $id) { id }
}

query Wallets {
  wallets(page: 1, limit: 2) { items { id label address network type balanceCache metadata ownerUserId status createdAt updatedAt } pageInfo { total page limit totalPages } }
}

query WalletsByOwner($owner: String) {
  wallets(ownerUserId: $owner, limit: 100) { items { id ownerUserId } pageInfo { total } }
}

query TooMany {
  wallets(limit: 101) { pageInfo { total } }
}

mutation Update($id: ID!, $input: UpdateWalletMetadataInput!) {
  updateWalletMetadata(id: $id, input: $input) { id label metadata updatedAt }
}

mutation Hijack($id: ID!) {
  updateWalletMetadata(id: $id, input: { label: "hijack" }) { id }
}

mutation AuditorWrite($id: ID!) {
  updateWalletMetadata(id: $id, input: { label: "audit" }) { id }
}

mutation Send($input: CreateTransactionInput!) {
  createTransaction(input: $input) { id walletId txid type amount feeRate status confirmations createdAt updatedAt }
}

mutation SendReplay($input: CreateTransactionInput!) {
  createTransaction(input: $input) { id status }
}

mutation SendConflict($input: CreateTransactionInput!) {
  createTransaction(input: $input) { id }
}

mutation BadKey {
  createTransaction(input: { walletId: "{{walletId}}", amount: "1000", feeRate: "1", destinationAddress: "tb1qw508d6qejxtdg4y5r3zarvary0c5xw7kxpjzsx", idempotencyKey: "bad key!" }) { id }
}

mutation BadAmount($key: String!) {
  createTransaction(input: { walletId: "{{walletId}}", amount: "0.5", feeRate: "1", destinationAddress: "tb1qw508d6qejxtdg4y5r3zarvary0c5xw7kxpjzsx", idempotencyKey: $key }) { id }
}

mutation BadAddress($key: String!) {
  createTransaction(input: { walletId: "{{walletId}}", amount: "1000", feeRate: "1", destinationAddress: "bc1qw508d6qejxtdg4y5r3zarvary0c5xw7kv8f3t4", idempotencyKey: $key }) { id }
}

mutation Unfunded($key: String!) {
  createTransaction(input: { walletId: "{{gqlWalletId}}", amount: "1000", feeRate: "1", destinationAddress: "tb1qw508d6qejxtdg4y5r3zarvary0c5xw7kxpjzsx", idempotencyKey: $key }) { id }
}

mutation NotMine($key: String!) {
  createTransaction(input: { walletId: "{{walletId}}", amount: "1000", feeRate: "1", destinationAddress: "tb1qw508d6qejxtdg4y5r3zarvary0c5xw7kxpjzsx", idempotencyKey: $key }) { id }
}

query Tx($id: ID!) {
  transaction(id: $id) { id walletId txid type amount feeRate status confirmations createdAt updatedAt }
}

query OtherTx($id: ID!) {
  transaction(id: $id) { id }
}

query PendingTxs($walletId: String, $from: String) {
  transactions(walletId: $walletId, status: PENDING, from: $from, page: 1, limit: 50) {
    items { id walletId txid type amount feeRate status confirmations createdAt updatedAt }
    pageInfo { total page limit totalPages }
  }
}

query FailedTxs($walletId: String) {
  transactions(walletId: $walletId, status: FAILED, to: "2999-01-01T00:00:00.000Z") { items { id status amount } pageInfo { total } }
}

query Sent($walletId: String) {
  broadcast: transactions(walletId: $walletId, status: BROADCAST) { items { id } }
  confirmed: transactions(walletId: $walletId, status: CONFIRMED) { items { id } }
}

query BadStatus {
  transactions(status: SETTLED) { pageInfo { total } }
}

query TooDeep {
  __schema { types { fields { type { ofType { ofType { ofType { ofType { ofType { name } } } } } } } } }
}

query Introspect {
  __schema { queryType { name } mutationType { name } }
}

mutation Broken {
  createWallet(input: { label: "x" network: TESTNET type: HOT }
}
